        return {}
    else:
        ret = {}

        # If there are no tokens, just map each line number to its line
        if not file_tokens:
            for i, line in enumerate(self.lines, start=1):
                ret[i] = line
            return ret

        min_line = len(self.lines) + 2
        max_line = -1
        for tp, _, (s_line, _), (e_line, _), _ in file_tokens:
            if tp == tokenize.ENDMARKER or tp == tokenize.DEDENT:
                continue

            min_line = min(min_line, s_line)
            max_line = max(max_line, e_line)

            if tp in (tokenize.NL, tokenize.NEWLINE):
                ret.update(self._noqa_line_range(min_line, max_line))

                min_line = len(self.lines) + 2
                max_line = -1

        # If we didn't process any tokens with newlines, we need to handle the last token
        if min_line <= len(self.lines) and max_line >= 1:
            ret.update(self._noqa_line_range(min_line, max_line))

        return ret

